// AddConhecimentoTransportes adds the given related objects to the existing relationships
// of the csticm, optionally inserting them as new records.
// Appends related to o.R.ConhecimentoTransportes.
// Sets related.R.Csticm appropriately.
func (o *Csticm) AddConhecimentoTransportes(ctx context.Context, exec boil.ContextExecutor, insert bool, related ...*ConhecimentoTransporte) error {
	var err error
	for _, rel := range related {
		if insert {
			rel.CsticmsID = o.CsticmsID
			if err = rel.Insert(ctx, exec, boil.Infer()); err != nil {
				return errors.Wrap(err, "failed to insert into foreign table")
			}
		} else {
			updateQuery := fmt.Sprintf(
				"UPDATE `conhecimento_transporte` SET %s WHERE %s",
				strmangle.SetParamNames("`", "`", 0, []string{"csticms_id"}),
				strmangle.WhereClause("`", "`", 0, conhecimentoTransportePrimaryKeyColumns),
			)
			values := []interface{}{o.CsticmsID, rel.CTID}

			if boil.IsDebug(ctx) {
				writer := boil.DebugWriterFrom(ctx)
				fmt.Fprintln(writer, updateQuery)
				fmt.Fprintln(writer, values)
			}
			if _, err = exec.ExecContext(ctx, updateQuery, values...); err != nil {
				return errors.Wrap(err, "failed to update foreign table")
			}

			rel.CsticmsID = o.CsticmsID
		}
	}

	if o.R == nil {
		o.R = &csticmR{
			ConhecimentoTransportes: related,
		}
	} else {
		o.R.ConhecimentoTransportes = append(o.R.ConhecimentoTransportes, related...)
	}

	for _, rel := range related {
		if rel.R == nil {
			rel.R = &conhecimentoTransporteR{
				Csticm: o,
			}
		} else {
			rel.R.Csticm = o
		}
	}
	return nil
}

